package top.monitorglobal.tv;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.Bundle;import android.widget.*;import java.io.*;import java.text.DateFormat;import org.json.*;
/** Owner-visible local report; nothing is uploaded automatically. */
public final class DiagnosticsActivity extends Activity {
 private TextView text;private File pending;
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(36,24,36,24);ScrollView scroll=new ScrollView(this);scroll.addView(content);setContentView(scroll);text=new TextView(this);text.setTextColor(Color.WHITE);text.setTextSize(18);content.addView(text);button(content,"Atualizar leitura salva",()->showReport());button(content,"Salvar diagnóstico em arquivo JSON",()->{try{pending=RuntimeDiagnostics.export(this);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"monitor-global-tv-diagnostico.json");startActivityForResult(i,34);}catch(IOException|ActivityNotFoundException e){Toast.makeText(this,"Sem gerenciador de arquivos. Tente Compartilhar diagnóstico.",Toast.LENGTH_LONG).show();}});button(content,"Compartilhar diagnóstico",()->{try{RuntimeDiagnostics.export(this);Uri uri=Uri.parse("content://"+getPackageName()+".diagnostics/report");Intent i=new Intent(Intent.ACTION_SEND).setType("application/json").putExtra(Intent.EXTRA_STREAM,uri);i.setClipData(ClipData.newRawUri("Diagnóstico local",uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Exportar diagnóstico local"));}catch(IOException|ActivityNotFoundException e){Toast.makeText(this,"Nenhum aplicativo de compartilhamento disponível neste aparelho.",Toast.LENGTH_LONG).show();}});showReport();}
 private void button(LinearLayout row,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->action.run());row.addView(b);}
 private void showReport(){JSONObject r=RuntimeDiagnostics.read(this);JSONArray rows=r.optJSONArray("samples");if(rows==null||rows.length()==0){text.setText("DIAGNÓSTICO LOCAL\n\nAtive o monitoramento. A primeira leitura é feita em segundo plano; depois, uma por minuto. Nenhum dado é enviado automaticamente.\n\nVolte aqui para atualizar ou exportar a leitura salva.");return;}JSONObject last=rows.optJSONObject(rows.length()-1),frame=last.optJSONObject("banner");text.setText("DIAGNÓSTICO LOCAL · "+r.optString("device")+"\nAplicativo "+r.optString("version")+" · Android API "+r.optInt("sdk")+"\nÚltima leitura: "+DateFormat.getDateTimeInstance().format(new java.util.Date(last.optLong("at")))+"\nLeituras neste processo: "+r.optLong("sampleCount")+" · guardadas: "+rows.length()+"/"+RuntimeDiagnostics.MAX_SAMPLES+"\n\nMemória PSS do processo: "+(last.optBoolean("pssAvailable")?mb(last.optLong("pssKb")*1024):"indisponível nesta leitura")+"\nInicial: "+(r.optLong("baselinePssKb")>0?mb(r.optLong("baselinePssKb")*1024):"indisponível")+" · pico: "+(r.optLong("peakPssKb")>0?mb(r.optLong("peakPssKb")*1024):"indisponível")+"\nJava em uso: "+mb(last.optLong("javaUsedBytes"))+"\nAlocações nativas: "+mb(last.optLong("nativeAllocatedBytes"))+"\n\nDesenhos da tarja: "+(frame==null?0:frame.optLong("drawnFrames"))+"\nIntervalos maiores que 50 ms: "+(frame==null?0:frame.optLong("gapsOver50ms"))+"\nIntervalos maiores que 100 ms: "+(frame==null?0:frame.optLong("gapsOver100ms"))+"\n\nPSS, Java e nativa são medidas diferentes: não some os valores. Intervalos de desenho não são FPS nem medição completa da GPU. Coleta somente durante monitoramento, um registro por minuto, com retenção limitada; dados ficam neste aparelho. Salvar ou compartilhar depende dos aplicativos instalados na TV.");}
 private String mb(long bytes){return String.format(java.util.Locale.forLanguageTag("pt-BR"),"%.1f MiB",bytes/1048576.0);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=34||result!=RESULT_OK||data==null||data.getData()==null||pending==null)return;try(InputStream in=new FileInputStream(pending);OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException("Destino indisponível");byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Toast.makeText(this,"Diagnóstico salvo.",Toast.LENGTH_LONG).show();}catch(IOException e){Toast.makeText(this,"Não foi possível salvar.",Toast.LENGTH_LONG).show();}finally{pending=null;}}
}
